    from collections import deque
    def girth(G):
        best = float('inf')
        for s in G.nodes():
            dist = {s:0}
            parent = {s:None}
            q = deque([s])
            while q:
                u = q.popleft()
                for v in G.neighbors(u):
                    if v not in dist:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        q.append(v)
                    elif parent[u] != v:
                        c = dist[u]+dist[v]+1
                        if c < best: best = c
        return best
    g = girth(G)
