# Correct McGee LCF: [-12, 7, -7]^8 per Wikipedia
n = 24
from collections import deque, Counter

def build(lcf):
    edges = set()
    for i in range(n):
        a, b = i, (i+1) % n
        edges.add((min(a,b), max(a,b)))
    for i in range(n):
        j = (i + lcf[i % len(lcf)]) % n
        edges.add((min(i,j), max(i,j)))
    return sorted(edges)

def girth2(edges):
    adj = {i:set() for i in range(n)}
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    best = float('inf')
    for s in range(n):
        dist = {s:0}; parent = {s:-1}; q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u]+1; parent[v] = u; q.append(v)
                elif parent[u] != v:
                    c = dist[u]+dist[v]+1
                    if c < best: best = c
    return best

for lcf in [[-12,7,-7], [12,7,-7], [13,-13,-9,9], [-13,-9,7,-7,9,13]]:
    e = build(lcf)
    print(lcf, "edges:", len(e), "girth:", girth2(e))

